content:
:root { --ink:#273043; --muted:#667085; --paper:#f6f3ed; --card:#ffffff; --teal:#007c91; --coral:#e07a5f; --gold:#d4a72c; }
body { background:var(--paper); color:var(--ink); font-family:Inter,system-ui,-apple-system,"Segoe UI",sans-serif; }
.container-fluid { max-width:1440px; padding:0 3vw 2rem; }
.hero { margin:0 -3vw 2rem; padding:3.2rem 5vw 2.8rem; color:white; background:linear-gradient(125deg,#1d2a3a 0%,#124f5a 58%,#007c91 100%); }
.hero h1 { font-size:clamp(2.2rem,5vw,4.6rem); font-weight:750; letter-spacing:-.045em; margin:.2rem 0 .7rem; }
.hero p { max-width:820px; font-size:1.15rem; color:#dceef1; margin:0; }
.eyebrow { color:#ffd27a; font-weight:750; letter-spacing:.16em; font-size:.76rem; }
.nav-pills>li>a { color:var(--ink); border-radius:10px; margin-bottom:.45rem; font-weight:650; padding:.9rem 1rem; }
.nav-pills>li.active>a,.nav-pills>li.active>a:focus,.nav-pills>li.active>a:hover { background:var(--teal); }
.section-heading { border-bottom:1px solid #d8d5cf; margin-bottom:1.3rem; }
.section-heading h2 { font-size:2rem; font-weight:750; letter-spacing:-.025em; margin-top:0; }
.section-heading p { color:var(--muted); font-size:1.05rem; }
.control-card,.plot-card,.table-card,.insight-card,.explain-card,.compare-card,.metric-card { background:var(--card); border:1px solid #e1ded7; border-radius:16px; padding:1.25rem; margin-bottom:1rem; box-shadow:0 6px 22px rgba(39,48,67,.05); }
.control-card { position:sticky; top:1rem; }
.btn-primary { background:var(--teal); border-color:var(--teal); width:100%; font-weight:700; padding:.7rem; }
.metric-card { display:flex; justify-content:space-between; align-items:baseline; border-left:5px solid var(--gold); }
.metric-card span { color:var(--muted); font-size:.88rem; }
.metric-card strong { font-size:1.5rem; }
.metric-copy { display:flex; flex-direction:column; gap:.2rem; max-width:72%; }
.metric-copy small,.plot-note { color:var(--muted); font-size:.86rem; line-height:1.4; font-weight:400; }
.plot-note { margin:.6rem .25rem 0; padding-top:.75rem; border-top:1px solid #ece8e0; }
.formula { background:#eef7f8; border-radius:10px; padding:1rem; font-family:Georgia,serif; font-size:1.12rem; margin:.75rem 0; }
.insight-card { border-left:5px solid var(--teal); }
.table { background:white; }
.table>thead>tr>th { border-bottom:2px solid var(--teal); }
h3 { font-weight:700; font-size:1.25rem; }
footer { text-align:center; color:var(--muted); padding:2.5rem 0 1rem; font-size:.86rem; }
@media (max-width:768px) { .hero { padding-top:2.2rem; } .control-card { position:static; } .nav-stacked { margin-bottom:1.5rem; } }
